package com.example.banking.config;
import io.swagger.v3.oas.models.*;import io.swagger.v3.oas.models.info.*;import io.swagger.v3.oas.models.security.*;import org.springframework.context.annotation.*;
@Configuration public class OpenApiConfig {@Bean OpenAPI bankingApi(){return new OpenAPI().info(new Info().title("Secure Banking API").version("v1").description("JWT-secured banking and transaction API. Refresh tokens are opaque, single-use credentials and must be kept secret.")).components(new Components().addSecuritySchemes("bearerAuth",new SecurityScheme().type(SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT")));}}
